mapper.select:
SELECT COUNT(*)
FROM games g
    INNER JOIN teams t ON t.id = g.team_id
    INNER JOIN seasons s ON s.id = g.season_id
WHERE t.slug = #{teamSlug}
  AND t.is_active = true
  AND t.deleted_at IS NULL
  AND s.team_id = g.team_id

      AND s.year = #{seasonYear}


      AND g.tournament_id = #{tournamentId}

  AND g.status = #{status}
